import { scenario } from "@opensoftware/testkit";
import { CLONE, DEMO_PACKAGE, DEMO_PREFIXES, nestedCheckouts, putAll, WORKTREE } from "./repo.ts";

const README =
  "# demo\n\n## Commands\n\n<!-- generated by make docs from src/cli.ts --help: do not edit -->\n\n## Notes\n\nNone.\n";

scenario("SCN-REPO-159", async ({ sut, given, when, then }) => {
  await given('a module whose "src/cli.ts --help" lists the command "demo run" as "Run the demo."', async () => {
    await sut.files.put("$INPUT/docs/reference/scenario-prefixes.md", DEMO_PREFIXES);
    await sut.files.put("$INPUT/modules/demo/package.json", DEMO_PACKAGE);
    await sut.files.put(
      "$INPUT/modules/demo/src/cli.ts",
      'process.stdout.write("usage: demo <command>\\n\\nCommands:\\n  demo run    Run the demo.\\n");\n',
    );
  });

  await given(
    'its README has the marker "generated by make docs from src/cli.ts --help" under "## Commands"',
    async () => {
      await sut.files.put("$INPUT/modules/demo/README.md", README);
    },
  );

  await given(
    'the same module, with a CLI that fails, in the worktree ".claude/worktrees/other" (a ".git" file) and the clone "vendor/clone" (a ".git" folder)',
    async () => {
      await putAll(
        sut,
        nestedCheckouts({
          "modules/demo/package.json": DEMO_PACKAGE,
          "modules/demo/src/cli.ts": 'process.stderr.write("not built\\n");\nprocess.exit(1);\n',
          "modules/demo/README.md": README,
        }),
      );
    },
  );

  let run: Awaited<ReturnType<typeof sut.cli>>;
  await when('the developer runs "osf docs"', async () => {
    run = await sut.cli(["docs"]);
  });

  await then("the command exits with code 0", async () => {
    expect(run.exitCode, run.stdout + run.stderr).toBe(0);
  });

  await then('the module README has the row "| `demo run` | Run the demo. |"', async () => {
    expect(await sut.files.read("$INPUT/modules/demo/README.md")).toContain("| `demo run` | Run the demo. |");
  });

  await then("the README files of the worktree and the clone are unchanged", async () => {
    expect(await sut.files.read(`$INPUT/${WORKTREE}/modules/demo/README.md`)).toBe(README);
    expect(await sut.files.read(`$INPUT/${CLONE}/modules/demo/README.md`)).toBe(README);
  });

  await when('the developer runs "osf check DOCS-GEN"', async () => {
    run = await sut.cli(["check", "DOCS-GEN"]);
  });

  await then("the command exits with code 0", async () => {
    expect(run.exitCode, run.stdout + run.stderr).toBe(0);
  });
});
